INSERT OR REPLACE INTO kb_pages (id, data) VALUES (1, '{"content": "The First Build is a fixed-scope engagement: one week, one workflow, one working system, with a human check built in. The standard rate is $126/hour; the first 3 clients get the founding rate of $75/hour. A typical build runs about 20 hours across the week. The workflow teaser asset shows the client''s task today \u2014 usually about 5 steps with a stall \u2014 and with a build: 2 human checks, the rest runs.", "createdAt": "2026-11-07T21:08:14.792Z", "id": 1, "title": "The First Build \u2014 the offer", "url": null}');
INSERT OR REPLACE INTO kb_pages (id, data) VALUES (2, '{"content": "A fit call is a 20-minute call held on Thursday or Friday afternoons. When a prospect replies to outreach at any step, the outreach sequence stops and the next step is booking a fit call \u2014 no further touches go out. Cold-call blocks are Monday and Tuesday, 10 AM to 12 PM Eastern.", "createdAt": "2026-11-07T21:08:14.827Z", "id": 2, "title": "Fit calls and how booking works", "url": null}');
INSERT OR REPLACE INTO kb_pages (id, data) VALUES (3, '{"content": "The First Build fits Cincinnati-area service operators with roughly 5\u201350 staff whose team repeats one task daily or weekly in inboxes, spreadsheets, forms, or copy-paste between tools \u2014 intake, quotes, renewals, invoicing, tenant inquiries. The operator can name the task, and someone checks the work today. It does not fit chains or large firms where no owner is reachable and procurement decides.", "createdAt": "2026-11-07T21:08:14.853Z", "id": 3, "title": "Who The First Build fits", "url": null}');
